CustomField.formula:
if(Daylight_Savings_Time__c, 

if (not (isblank(Participant_Time_Out_Override__c)), Participant_Time_Out_Override__c, 

if (isnull (Participant_Date_Time_Out__c), null,

IF( 
OR( 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 5/24 ), 12, 2 ) ) = 0, 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 5/24 ), 12, 2 ) ) = 12 
), 
"12", 
TEXT( VALUE( MID( TEXT( Participant_Date_Time_Out__c - 5/24 ), 12, 2 ) ) 
- 
IF( 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 5/24 ), 12, 2 ) ) < 12, 
0, 
12 
) 
) 
) 
& ":" & 
MID( TEXT( Participant_Date_Time_Out__c - 5/24 ), 15, 2 ) 
& " " & 
IF( 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 5/24 ), 12, 2 ) ) < 12, 
"AM", 
"PM" 
)

)),

if (not (isblank(Participant_Time_Out_Override__c)), Participant_Time_Out_Override__c, 

if (isnull (Participant_Date_Time_Out__c), null,

IF( 
OR( 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 6/24 ), 12, 2 ) ) = 0, 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 6/24 ), 12, 2 ) ) = 12 
), 
"12", 
TEXT( VALUE( MID( TEXT( Participant_Date_Time_Out__c - 6/24 ), 12, 2 ) ) 
- 
IF( 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 6/24 ), 12, 2 ) ) < 12, 
0, 
12 
) 
) 
) 
& ":" & 
MID( TEXT( Participant_Date_Time_Out__c - 6/24 ), 15, 2 ) 
& " " & 
IF( 
VALUE( MID( TEXT( Participant_Date_Time_Out__c - 6/24 ), 12, 2 ) ) < 12, 
"AM", 
"PM" 
)

)))
